/* MathWorksSounds.js — build 4 LOUD
   Shared MathWorks transition cue.
   Higher, brighter C5-E5-G5 chime optimized for phone speakers.
*/
(function(w){
  "use strict";
  const cue = document.createElement("audio");
  cue.preload = "auto";
  cue.src = "data:audio/wav;base64,";
  cue.loop = false;
  cue.volume = 1.0;

  document.addEventListener("DOMContentLoaded", function(){
    if(!cue.parentNode) document.body.appendChild(cue);
    try{ cue.load(); }catch(e){}
  });

  function transition(){
    try{
      cue.pause();
      cue.currentTime = 0;
      cue.volume = 1.0;
      const p = cue.play();
      if(p && p.catch) p.catch(function(err){
        console.log("MathWorks transition sound blocked:", err);
      });
    }catch(e){
      console.log("MathWorks transition sound error:", e);
    }
  }

  w.MathWorksSounds = {
    build: 4,
    transition: transition
  };
})(window);
